import hashlib,json
from training import evaluate_high_volatility_price_level_occupation_relay_economics as economics
def test_hvplo_train_rejection_is_terminal_and_later_stages_are_sealed():
 p=economics.OUTPUTS["train"];assert hashlib.sha256(p.read_bytes()).hexdigest()=="90e7c0e0dedbb5422cb6d103611c3e7df1740ecf43b7ca4716fc23ee8c36589f";x=json.loads(p.read_text());core={k:v for k,v in x.items() if k!="manifest_hash"};assert x["manifest_hash"]==economics.canonical_hash(core);assert x["passed"] is False and x["decision"]=="terminal_reject_no_repair" and x["later_stage_outcomes_opened"] is False;assert x["primary"]["base"]["absolute_return_pct"]>5 and x["primary"]["stress"]["absolute_return_pct"]>3;assert x["checks"]["cagr_to_strict_mdd_min_3"] is False and x["checks"]["cluster_signflip_p_max_0_1"] is False and x["checks"]["each_calendar_half_positive"] is False;assert not economics.OUTPUTS["test"].exists() and not economics.OUTPUTS["eval"].exists() and not economics.OUTPUTS["final"].exists()
